	home := strings.TrimSpace(profile.Home)
	if home == "" {
		home = "local"
	}
	var places []string
	for _, card := range profile.Cards {
		if card.IsDeleted {
			continue
		}
		switch {
		case card.Kind == "local":
			places = append(places, "local")
		case card.Kind == "provider":
			place := "account:" + card.AccountID
			if card.AddressBookID != "" {
				place = "book:" + card.AddressBookID
			}
			places = append(places, place)
		}
	}
